// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(uint256 am) public {
        // Bound am to avoid overflow issues and keep it reasonable
        am = bound(am, 0, 1000000 ether);

        // Call Collect - it may revert due to insufficient balance or other conditions
        (bool success, ) = address(c).call{value: 0}(abi.encodeWithSignature("Collect(uint256)", am));

        // Rule: After any Collect call that completes without revert, MinSum must equal 1 ether
        if (success) {
            assertTrue(c.MinSum() == 1 ether, "MinSum must remain 1 ether after non-reverting Collect");
        }
    }
}

